// Kit inicial por vocação — entregue e equipado automaticamente na 1ª escolha de vocação
// (selectVocation, chamado na criação do personagem, ver characterUseCases.js). Fiel ao
// Dawnport TRAINING Set real do Tibia (TibiaWiki: Dawnport Set) — o kit dado ao sair pelo
// portão da vocação na ilha inicial, já que neste jogo não existe uma etapa de nível 8
// separada da criação (o Graduate Set do Tibia real não se aplica aqui).
// Quantidade de munição no kit inicial do paladino: como a munição é um item
// EMPILHÁVEL e consumível (mesmo com consumeAmmo desligado por padrão, ver
// adminConfig), entregar 1 só é o mesmo que "sem flecha" na prática — o
// paladino recém-criado começa com uma pilha de verdade da flecha mais fraca
// (simple_arrow), como no Dawnport real. Usado no cliente (selectVocation)
// e no servidor (grant do kit) pra ficarem idênticos.
export const STARTER_AMMO_QTY = 100;

export const STARTER_KITS = {
  knight:   { weapon: 'dagger',        armor: 'leather_armor', shield: 'wooden_shield', helmet: 'leather_helmet', legs: 'leather_legs', boots: 'leather_boots' },
  paladin:  { weapon: 'bow', ammo: 'simple_arrow', armor: 'leather_armor',          helmet: 'leather_helmet', legs: 'leather_legs', boots: 'leather_boots' },
  sorcerer: { weapon: 'the_scorcher', armor: 'leather_armor', shield: 'spellbook_of_the_novice', helmet: 'leather_helmet', legs: 'leather_legs', boots: 'leather_boots' },
  druid:    { weapon: 'the_chiller',  armor: 'leather_armor', shield: 'spellbook_of_the_novice', helmet: 'leather_helmet', legs: 'leather_legs', boots: 'leather_boots' },
};

// Supply inicial por vocação (poções/comida/runas), entregue junto com o STARTER_KITS
// na 1ª escolha de vocação. Fiel às quantidades reais do TibiaWiki (Dawnport): cada
// vocação recebia 1 Meat + Mana/Small Health Potions em proporção diferente (mago
// ganha mais mana, paladino é o meio-termo, knight ganha mais cura), mais 1-2
// Light Stone Shower/Lightest Missile Rune pros vocacionados que usam magia
// (paladino, sorcerer, druid — knight não recebe runas no Dawnport real).
export const STARTER_SUPPLIES = {
  knight:   { meat: 1, mana_potion: 2,  small_health_potion: 10 },
  paladin:  { meat: 1, mana_potion: 5,  small_health_potion: 7, light_stone_shower_rune: 1, lightest_missile_rune: 1 },
  sorcerer: { meat: 1, mana_potion: 10, small_health_potion: 2, light_stone_shower_rune: 2, lightest_missile_rune: 2 },
  druid:    { meat: 1, mana_potion: 10, small_health_potion: 2, light_stone_shower_rune: 2, lightest_missile_rune: 2 },
};

export const EQUIPMENT_SLOTS = ['helmet', 'weapon', 'armor', 'shield', 'ammo', 'ring', 'legs', 'boots'];
export const EQUIPPABLE_TYPES = ['weapon', 'armor', 'shield', 'helmet', 'ammo', 'ring', 'legs', 'boots'];
export const CONSUMABLE_TYPES = ['potion', 'rune', 'food'];

// Pool de fallback pra relíquia de boss SEM item equipável no próprio loot
// (ver application/huntUseCases.js: resolveMonsterKill) — em vez de sortear
// entre TODOS os itens equipáveis do jogo (bug real: Wolf, boss de zona sem
// loot equipável, chegou a dropar Demon Shield, item de 15000g), o teto de
// preço escala com a XP do monstro, então um bicho fraco só sorteia
// equipamento de tier compatível.
const RELIC_FALLBACK_MIN_SELL_CAP = 50;
const RELIC_FALLBACK_XP_TO_SELL = 5;
export function equippableFallbackPool(xp) {
  const cap = Math.max(RELIC_FALLBACK_MIN_SELL_CAP, (xp || 0) * RELIC_FALLBACK_XP_TO_SELL);
  return Object.keys(ITEMS).filter(id => EQUIPPABLE_TYPES.includes(ITEMS[id].type) && (ITEMS[id].sell || 0) <= cap);
}

// Tipos de ARMA que cada vocação pode empunhar (fiel ao Tibia: cada profissão
// usa sua classe de arma). Armadura/elmo/anel/etc. não são restritos aqui. A
// munição (ammo) é exclusiva do paladino. Ver equipItem em inventoryUseCases.
const VOCATION_WEAPON_TYPES = {
  knight:   ['sword', 'axe', 'club'],
  paladin:  ['distance'],
  sorcerer: ['magic'],
  druid:    ['magic'],
};
export function canVocationEquip(item, vocation) {
  if (!item || !vocation) return true;
  if (item.type === 'weapon') return (VOCATION_WEAPON_TYPES[vocation] || []).includes(item.weaponType);
  if (item.type === 'ammo') return vocation === 'paladin'; // só o paladino usa munição
  return true; // demais peças (armadura/elmo/anel/calças/botas/escudo) livres
}
// Motivo do bloqueio (pra mensagem), ou null se pode equipar. `t` é o
// tradutor (ver i18n/i18n.js) injetado por quem chama — este arquivo é dado
// puro (sem DOM/localStorage), então não importa i18n.js diretamente.
// `level` e opcional so por compatibilidade com chamadas antigas; sempre que
// existir, o requisito de nivel do item e cobrado. No Tibia a municao tem nivel
// minimo (Power Bolt 55, Infernal Bolt 110, Spectral Bolt 150...) e aqui nao
// era cobrado em lugar nenhum: dava pra equipar Spectral Bolt no nivel 1.
export function equipBlockReason(item, vocation, t, level = null) {
  if (level != null && item.reqLevel && level < item.reqLevel) {
    return t('items.reqLevel', { level: item.reqLevel });
  }
  if (canVocationEquip(item, vocation)) return null;
  if (item.type === 'weapon') return t('items.blockWrongWeapon');
  if (item.type === 'ammo') return t('items.blockAmmoOnly');
  return t('items.blockCannotEquip');
}

// Requisito de nível/vocação de uma poção, fiel ao Tibia (ver reqLevel/reqVoc
// nas poções acima). Retorna null se PODE usar, ou uma string com o motivo do
// bloqueio (pra mostrar ao jogador). Poções sem requisito (Health/Mana Potion)
// nunca bloqueiam. Usado no uso manual (inventoryUseCases), no auto-uso do RTC
// (huntUseCases) e na exibição (loja/RTC). `t` é o tradutor injetado (ver acima).
const VOC_DISPLAY = { knight: 'Knight', paladin: 'Paladin', sorcerer: 'Sorcerer', druid: 'Druid' };
// `t` é opcional: quando ausente (ver canUsePotion abaixo, que só quer saber
// SE está bloqueado, não a mensagem), retorna um valor truthy qualquer em vez
// de chamar t() — evita exigir o tradutor de quem só precisa do booleano.
export function potionUseBlockReason(item, vocation, level, t) {
  if (!item) return null;
  if (item.reqLevel && level < item.reqLevel) return t ? t('items.reqLevel', { level: item.reqLevel }) : true;
  if (item.reqVoc && vocation && !item.reqVoc.includes(vocation)) {
    return t ? t('items.reqVocOnly', { vocs: item.reqVoc.map(v => VOC_DISPLAY[v] || v).join('/') }) : true;
  }
  return null;
}
export function canUsePotion(item, vocation, level) {
  return potionUseBlockReason(item, vocation, level) === null;
}

// Rótulo estático do requisito de uma poção (pra loja/RTC), ex.:
// "Level 50 · Knight/Paladin". Vazio quando não há requisito. `t` é o
// tradutor injetado (ver acima).
export function potionReqLabel(item, t) {
  if (!item || (!item.reqLevel && !item.reqVoc)) return '';
  const parts = [];
  if (item.reqLevel) parts.push(t('items.levelLabel', { level: item.reqLevel }));
  if (item.reqVoc) parts.push(item.reqVoc.map(v => VOC_DISPLAY[v] || v).join('/'));
  return parts.join(' · ');
}

// Um valor de slot de equipamento (G.equipment[slot]) pode ser um itemId comum
// (chave direta de ITEMS) OU o id de uma Relíquia (G.relics — ver
// domain/gameState.js), no formato "relic_<n>". Esta função é o único critério
// usado no jogo inteiro pra distinguir os dois formatos.
export function isRelicId(id) {
  return typeof id === 'string' && id.startsWith('relic_');
}

// Resolve o item "efetivo" equipado num slot: um itemId comum vira
// ITEMS[itemId] direto; o id de uma Relíquia vira uma cópia do item base com
// o stat principal reforçado pelo bônus de raridade (ver domain/rarity.js).
// `relics` é passada explicitamente (em vez de ler G direto) pra manter esta
// função pura — quem chama passa G.relics (ver application/stats.js).
// Ponto único de resolução: todo cálculo de stat/skill que hoje lê
// ITEMS[equipment[slot]] deve passar por aqui em vez de duplicar o
// if (isRelicId(...)) em cada lugar.
export function resolveEquippedItem(slotValue, relics) {
  if (!slotValue) return null;
  if (!isRelicId(slotValue)) return ITEMS[slotValue] || null;
  const relic = (relics || []).find(r => r.id === slotValue);
  if (!relic) return null;
  const base = ITEMS[relic.itemId];
  if (!base) return null;
  const statKey = primaryStatKeyForItem(base);
  if (!statKey) return { ...base };
  return { ...base, [statKey]: Math.round(base[statKey] * (1 + relic.bonusPct)) };
}
